window.LECCIONES = window.LECCIONES || {};
/* HTML: cada sección tiene explicación (b), ideas clave (k), tabla de atributos (a),
   ejemplo editable (c), error común (e) y consejo (tip). v: 0 = sin vista previa. */
LECCIONES.html = { lang: 'html', capitulos: [
  { t: `Fundamentos`, d: `Qué es HTML, cómo se escribe una etiqueta y la estructura de todo documento.`, secciones: [
    { n: `1.1`, t: `¿Qué es HTML?`, m: `4 min`,
      b: [`HTML (HyperText Markup Language) es el lenguaje que describe la estructura y el contenido de una página web. No es un lenguaje de programación: no tiene variables, condiciones ni bucles. Lo que hace es marcar qué es cada trozo de contenido: esto es un título, esto un párrafo, esto una imagen, esto un enlace.`,
          `Una web se construye con tres capas. HTML pone el contenido y su significado, CSS decide cómo se ve (colores, tamaños, posición) y JavaScript añade comportamiento (reaccionar a clics, pedir datos…). Separarlas hace el código más fácil de mantener: puedes rediseñar una web entera cambiando solo el CSS.`,
          `El navegador descarga el archivo .html, lo lee de arriba abajo y construye con él un árbol de objetos llamado DOM (Document Object Model). Ese árbol es lo que luego pinta en pantalla y lo que JavaScript puede modificar.`],
      k: [`HTML = estructura y significado; CSS = aspecto; JavaScript = comportamiento.`, `Es un lenguaje de marcado, no de programación.`, `Los archivos se guardan con extensión .html y la página principal suele llamarse index.html.`, `El navegador convierte el HTML en un árbol de elementos: el DOM.`],
      c: `<h1>Mi primera web</h1>\n<p>Hola, DAW. Esto es un párrafo.</p>\n<p>Y esto es <strong>otro</strong> párrafo.</p>`,
      tip: `abrid cualquier web y pulsad Ctrl+U para ver su HTML, o F12 para ver el DOM en las herramientas de desarrollo.` },
    { n: `1.2`, t: `Anatomía de un elemento`, m: `4 min`,
      b: [`Un elemento HTML tiene tres partes: la etiqueta de apertura (<p>), el contenido y la etiqueta de cierre (</p>), que lleva una barra. El nombre de la etiqueta dice qué tipo de contenido es.`,
          `Las etiquetas de apertura pueden llevar atributos, que añaden información extra con la forma nombre="valor". Por ejemplo, en un enlace el atributo href indica a dónde lleva. Un elemento puede tener varios atributos separados por espacios y su orden no importa.`,
          `Algunos elementos son vacíos (void): no tienen contenido ni etiqueta de cierre, porque toda su información va en los atributos. Los más comunes son <img>, <br>, <hr>, <input>, <meta> y <link>.`],
      k: [`<etiqueta atributo="valor">contenido</etiqueta>`, `Los atributos van siempre en la etiqueta de apertura, nunca en la de cierre.`, `Escribe los valores entre comillas dobles, aunque a veces funcione sin ellas.`, `Los elementos vacíos no se cierran: <img …> o <br>.`],
      a: [[`Etiqueta de apertura`, `Marca dónde empieza el elemento: <a>.`], [`Atributo`, `Información extra: href="contacto.html".`], [`Contenido`, `Lo que hay dentro: texto u otros elementos.`], [`Etiqueta de cierre`, `Marca el final, con barra: </a>.`]], at: `Partes de un elemento`, ah: [`Parte`, `Qué es`],
      c: `<a href="https://developer.mozilla.org/es/" title="Documentación">Ir a MDN</a>\n<br>\n<img src="https://placehold.co/160x80?text=Logo" alt="Logo de la clase">`,
      e: `olvidar cerrar una etiqueta. El navegador intenta arreglarlo, pero a menudo el resultado no es el esperado: todo lo que viene detrás queda en negrita o dentro de un enlace.`,
      tip: `indentad (sangrad) el código: si cada hijo va dos espacios más adentro que su padre, los cierres olvidados saltan a la vista.` },
    { n: `1.3`, t: `Anidamiento y jerarquía`, m: `4 min`,
      b: [`Los elementos se pueden meter unos dentro de otros. Cuando un elemento está dentro de otro, decimos que es su hijo, y el de fuera es su padre. Los elementos que comparten padre son hermanos. Esta jerarquía es exactamente el árbol DOM.`,
          `La regla de oro: las etiquetas se cierran en orden inverso al que se abrieron. Si abres <p> y luego <strong>, primero cierras </strong> y después </p>. Cruzar los cierres produce HTML inválido.`,
          `Además, no todo puede ir dentro de todo. Por ejemplo, un párrafo <p> no puede contener otro <p> ni una lista, y un <li> solo puede ir dentro de <ul>, <ol> o <menu>.`],
      k: [`Padre, hijo, hermano: el vocabulario del DOM.`, `Se cierra primero lo último que se abrió.`, `<p> solo puede contener contenido en línea (texto, enlaces, strong…).`, `CSS y JavaScript usan esta jerarquía para seleccionar elementos.`],
      c: `<!-- Bien -->\n<p>Esto es <strong>muy <em>importante</em></strong>.</p>\n\n<!-- Mal: cierres cruzados -->\n<p>Esto es <strong>muy importante</p></strong>`,
      e: `meter un <div> o una lista dentro de un <p>. El navegador cierra el párrafo automáticamente antes del <div>, y vuestro CSS deja de funcionar como esperabais.`,
      tip: `en VS Code, la extensión de colores de etiquetas emparejadas ayuda mucho a ver qué cierra con qué.` },
    { n: `1.4`, t: `El documento HTML5`, m: `5 min`,
      b: [`Todo documento HTML empieza con <!DOCTYPE html>, que le dice al navegador que use el modo estándar de HTML5. Sin esa línea, el navegador entra en «modo quirks» e imita fallos de navegadores antiguos.`,
          `Después viene el elemento raíz <html>, que envuelve todo. Su atributo lang indica el idioma de la página: lo usan los lectores de pantalla para pronunciar bien, los buscadores para clasificar y el navegador para ofrecer traducción.`,
          `Dentro de <html> hay siempre dos hijos: <head>, con información sobre la página que no se ve (título, codificación, estilos), y <body>, con todo el contenido visible.`],
      k: [`<!DOCTYPE html> en la primera línea, siempre.`, `<html lang="es"> declara el idioma.`, `head = información sobre la página; body = lo que se ve.`, `Solo puede haber un head y un body.`],
      a: [[`<!DOCTYPE html>`, `Activa el modo estándar de HTML5.`], [`<html lang="es">`, `Elemento raíz; lang indica el idioma.`], [`<head>`, `Metadatos: título, codificación, CSS, scripts.`], [`<body>`, `Todo el contenido visible de la página.`]], at: `Piezas del documento`, ah: [`Elemento`, `Función`],
      c: `<!DOCTYPE html>\n<html lang="es">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Festival DAW</title>\n</head>\n<body>\n  <h1>Festival DAW 2026</h1>\n  <p>Tres días de música en Madrid.</p>\n</body>\n</html>`,
      tip: `en VS Code, en un archivo .html vacío escribid ! y pulsad Tab: Emmet genera esta estructura completa.` },
    { n: `1.5`, t: `El head en detalle`, m: `5 min`, v: 0,
      b: [`El <head> contiene metadatos: información para el navegador, los buscadores y las redes sociales. Nada de lo que hay aquí aparece dentro de la página, pero sin ello la web puede verse mal o no encontrarse.`,
          `Lo mínimo es: <meta charset="utf-8"> para que se vean bien las tildes y la ñ; la meta viewport, para que en el móvil la página se adapte al ancho de la pantalla en lugar de verse diminuta; y <title>, el texto de la pestaña y del resultado en Google.`,
          `También se enlazan aquí las hojas de estilo con <link rel="stylesheet"> y los scripts con <script>. El favicon (icono de la pestaña) se enlaza con <link rel="icon">.`],
      k: [`charset utf-8 va lo primero dentro del head.`, `Sin meta viewport, la web no es responsive en móviles.`, `El title debe describir la página en menos de unos 60 caracteres.`, `Los scripts con defer se pueden poner en el head sin bloquear la carga.`],
      a: [[`<meta charset="utf-8">`, `Codificación de caracteres: tildes, ñ, emojis.`], [`<meta name="viewport" …>`, `Adapta el ancho al dispositivo (responsive).`], [`<title>`, `Texto de la pestaña y del resultado en buscadores.`], [`<meta name="description">`, `Resumen que muestra Google bajo el título.`], [`<link rel="stylesheet" href>`, `Enlaza un archivo CSS.`], [`<link rel="icon" href>`, `Icono de la pestaña (favicon).`], [`<script src defer>`, `Carga JavaScript sin bloquear el HTML.`]], at: `Etiquetas habituales del head`, ah: [`Etiqueta`, `Para qué sirve`],
      c: `<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Entradas — Festival DAW 2026</title>\n  <meta name="description" content="Compra tus entradas para el Festival DAW.">\n  <link rel="icon" href="favicon.svg">\n  <link rel="stylesheet" href="css/styles.css">\n  <script src="js/app.js" defer></script>\n</head>`,
      e: `poner contenido visible (un <h1>, un <p>) dentro del head. El navegador lo saca al body por su cuenta y la estructura queda desordenada.`,
      tip: `si las tildes salen como símbolos raros, revisad dos cosas: el charset y que VS Code guarde el archivo en UTF-8 (abajo a la derecha).` },
    { n: `1.6`, t: `Comentarios, espacios y mayúsculas`, m: `3 min`,
      b: [`Los comentarios se escriben entre <!-- y -->. El navegador los ignora, así que sirven para dejar notas o desactivar temporalmente un trozo de código. Ojo: cualquiera que vea el código fuente puede leerlos, así que nunca pongáis contraseñas ni datos privados.`,
          `HTML colapsa los espacios: varios espacios, tabulaciones o saltos de línea seguidos se muestran como un único espacio. Por eso pulsar Enter en el código no crea un salto de línea en la página; para eso hay etiquetas.`,
          `Las etiquetas no distinguen mayúsculas (<P> funciona igual que <p>), pero la convención es escribirlo todo en minúsculas.`],
      k: [`<!-- comentario --> no se muestra en la página.`, `Varios espacios o saltos de línea se ven como uno solo.`, `Escribe etiquetas y atributos en minúsculas.`, `Atajo en VS Code: Ctrl + / comenta la línea.`],
      c: `<!-- Cabecera de la página -->\n<h2>Horarios</h2>\n<p>Este      texto     tiene\n   muchos espacios\n   y saltos de línea.</p>\n<!-- <p>Este párrafo está desactivado</p> -->`,
      tip: `usad comentarios para marcar dónde empieza y acaba cada sección en proyectos de grupo: facilita los merges en Git.` }
  ]},
  { t: `Texto`, d: `Títulos, párrafos, formato con significado, citas y caracteres especiales.`, secciones: [
    { n: `2.1`, t: `Títulos h1–h6`, m: `4 min`,
      b: [`HTML tiene seis niveles de título: de <h1> (el más importante) a <h6>. No sirven para hacer el texto grande: sirven para crear el índice del documento. Los lectores de pantalla permiten saltar de título en título y Google los usa para entender de qué trata la página.`,
          `Lo habitual es un único <h1> por página con el tema principal, <h2> para las secciones y <h3> para las subsecciones. No conviene saltarse niveles (pasar de <h2> a <h4>) porque el índice queda roto.`],
      k: [`Un solo <h1> por página, normalmente.`, `Los niveles crean un índice: h2 dentro de h1, h3 dentro de h2…`, `Elige el nivel por la jerarquía, no por el tamaño.`, `El tamaño se cambia con CSS (font-size).`],
      c: `<h1>Festival DAW 2026</h1>\n<h2>Cartel</h2>\n<h3>Viernes</h3>\n<h3>Sábado</h3>\n<h2>Entradas</h2>`,
      e: `usar <h4> porque «se ve más pequeño». Si quieres un título más pequeño, usa el nivel correcto y cambia su tamaño con CSS.`,
      tip: `instalad la extensión HeadingsMap en el navegador: muestra el índice de títulos de cualquier web.` },
    { n: `2.2`, t: `Párrafos, saltos y separadores`, m: `3 min`,
      b: [`El texto normal va en párrafos <p>. El navegador separa cada párrafo con un margen arriba y abajo. Para cambiar de línea dentro de un mismo párrafo (en una dirección o un poema) se usa <br>, un elemento vacío.`,
          `<hr> representa un cambio de tema entre bloques de contenido y por defecto se dibuja como una línea horizontal. No uséis <br> repetidos para separar bloques: para dar espacio está el margin de CSS.`],
      k: [`<p> para cada párrafo.`, `<br> salta de línea dentro de un párrafo.`, `<hr> separa temas distintos.`, `El espacio entre bloques se controla con CSS, no con <br><br>.`],
      c: `<p>El festival se celebra en el recinto de IFEMA.</p>\n<p>Dirección:<br>\nAv. del Partenón, 5<br>\n28042 Madrid</p>\n<hr>\n<p>Organiza: clase de DAW.</p>`,
      tip: `si veis <br><br><br> en un proyecto, casi siempre es un margin que falta en el CSS.` },
    { n: `2.3`, t: `Formato con significado`, m: `5 min`,
      b: [`Hay etiquetas en línea que dan significado a una parte del texto. <strong> indica importancia y <em> énfasis (cambia el sentido de la frase al leerla). Por defecto se ven en negrita y cursiva, pero lo que importa es su significado: los lectores de pantalla los entonan.`,
          `<b> e <i> también ponen negrita y cursiva, pero sin significado extra: se usan para términos técnicos, nombres de obras o palabras en otro idioma. Otras etiquetas útiles son <mark> (resaltado), <small> (letra pequeña legal), <del> e <ins> (texto borrado o añadido), <sub> y <sup> (subíndice y superíndice) y <abbr> (abreviatura con su significado).`],
      k: [`strong = importante; em = énfasis.`, `b e i solo cambian el estilo, sin dar importancia.`, `<abbr title="…"> muestra el significado al pasar el ratón.`, `Para negrita puramente decorativa, mejor CSS (font-weight).`],
      a: [[`<strong>`, `Contenido importante o urgente.`], [`<em>`, `Énfasis que cambia el sentido de la frase.`], [`<mark>`, `Texto resaltado, como con un rotulador.`], [`<small>`, `Letra pequeña: avisos legales, copyright.`], [`<del> / <ins>`, `Texto eliminado / añadido (precios rebajados, cambios).`], [`<sub> / <sup>`, `Subíndice (H₂O) / superíndice (m²).`], [`<abbr title="…">`, `Abreviatura; title da el texto completo.`], [`<code> / <kbd>`, `Código / tecla que el usuario debe pulsar.`]], at: `Etiquetas de texto en línea`, ah: [`Etiqueta`, `Significado`],
      c: `<p><strong>Atención:</strong> las puertas cierran a las 23:00.</p>\n<p>Precio: <del>45 €</del> <ins>35 €</ins></p>\n<p>Fórmula del agua: H<sub>2</sub>O · Superficie: 300 m<sup>2</sup></p>\n<p>Estudio <abbr title="Desarrollo de Aplicaciones Web">DAW</abbr>.</p>\n<p>Pulsa <kbd>Ctrl</kbd> + <kbd>S</kbd> para guardar.</p>\n<p><small>© 2026 Festival DAW</small></p>`,
      tip: `pasad el ratón por encima de «DAW» en el resultado para ver cómo funciona abbr.` },
    { n: `2.4`, t: `Citas y código`, m: `4 min`,
      b: [`<blockquote> marca una cita larga sacada de otra fuente y se muestra sangrada; su atributo cite puede guardar la URL de origen. Para citas cortas dentro de una frase se usa <q>, que añade las comillas automáticamente. <cite> marca el título de una obra.`,
          `Para mostrar código, <code> marca un fragmento en línea. Si es un bloque de varias líneas, se mete dentro de <pre>, que respeta los espacios y saltos de línea tal cual (justo lo contrario del comportamiento normal de HTML).`],
      k: [`blockquote = cita en bloque; q = cita corta en línea.`, `cite = título de una obra.`, `pre respeta espacios y saltos de línea.`, `Bloque de código: <pre><code>…</code></pre>.`],
      c: `<blockquote cite="https://es.wikipedia.org/wiki/HTML">\n  <p>HTML es el lenguaje de marcado para la elaboración de páginas web.</p>\n</blockquote>\n<p>Como dijo el profe: <q>commit pronto, commit a menudo</q>.</p>\n<p>Lo leí en <cite>Pro Git</cite>.</p>\n<pre><code>git add .\ngit commit -m "Inicio"</code></pre>`,
      tip: `para mostrar < y > dentro de un bloque de código hay que escribir entidades (lo veréis en la siguiente sección).` },
    { n: `2.5`, t: `Entidades y caracteres especiales`, m: `3 min`,
      b: [`Algunos caracteres tienen significado en HTML: < y > abren y cierran etiquetas, y & empieza una entidad. Para mostrarlos como texto hay que escribir su entidad: &lt; para <, &gt; para > y &amp; para &.`,
          `También hay entidades para caracteres que no están en el teclado (&copy; ©, &euro; €, &rarr; →) y para el espacio duro &nbsp;, que impide que dos palabras se separen en líneas distintas (por ejemplo, «10 km»).`],
      k: [`&lt; → <   &gt; → >   &amp; → &`, `&nbsp; espacio que no se parte.`, `&copy; ©  &euro; €  &rarr; →`, `Con utf-8 puedes escribir tildes y ñ directamente, sin entidades.`],
      a: [[`&lt;  &gt;`, `Signos menor y mayor que (< >).`], [`&amp;`, `Ampersand (&).`], [`&quot;`, `Comillas dobles dentro de un atributo.`], [`&nbsp;`, `Espacio duro: no permite salto de línea.`], [`&copy;  &reg;`, `© y ®.`], [`&euro;`, `Símbolo del euro (€).`]], at: `Entidades más usadas`, ah: [`Entidad`, `Carácter`],
      c: `<p>Para un párrafo se escribe &lt;p&gt;texto&lt;/p&gt;.</p>\n<p>Tom &amp; Jerry · Entrada: 35&nbsp;&euro;</p>\n<p>Siguiente &rarr; Capítulo 3</p>\n<p>&copy; 2026 Festival DAW</p>`,
      tip: `cambiad &lt; por < en el ejemplo y veréis cómo el navegador intenta interpretarlo como etiqueta.` }
  ]},
  { t: `Listas y enlaces`, d: `Listas ordenadas, desordenadas y de definición; enlaces, anclas y menús.`, secciones: [
    { n: `3.1`, t: `Listas ul y ol`, m: `4 min`,
      b: [`Una lista desordenada <ul> agrupa elementos donde el orden no importa (ingredientes, características) y se muestra con viñetas. Una lista ordenada <ol> se usa cuando el orden importa (pasos de una receta, un ranking) y se numera sola.`,
          `Cada elemento va en un <li>. Las listas se pueden anidar: una sublista va dentro del <li> de su padre, no suelta dentro del <ul>. Las <ol> admiten atributos para cambiar la numeración.`],
      k: [`ul = sin orden; ol = con orden; li = cada elemento.`, `Una sublista va dentro de un <li>.`, `El estilo de la viñeta se cambia con CSS (list-style).`, `Los menús de navegación suelen ser listas.`],
      a: [[`start="5"`, `La <ol> empieza a contar en 5.`], [`reversed`, `Cuenta hacia atrás (ranking del 10 al 1).`], [`type="a | A | i | I | 1"`, `Letras, números romanos o números.`], [`value="10"` , `En un <li>: fuerza su número.`]], at: `Atributos de las listas ordenadas`,
      c: `<h3>Qué llevar</h3>\n<ul>\n  <li>Entrada (móvil o impresa)</li>\n  <li>DNI</li>\n  <li>Ropa cómoda\n    <ul>\n      <li>Chubasquero</li>\n      <li>Zapatillas</li>\n    </ul>\n  </li>\n</ul>\n<h3>Top 3 del cartel</h3>\n<ol reversed>\n  <li>Banda C</li>\n  <li>Banda B</li>\n  <li>Banda A</li>\n</ol>`,
      e: `poner el <ul> de la sublista entre dos <li>, fuera de cualquiera de ellos. Una ul solo puede tener hijos li.`,
      tip: `en Emmet, ul>li*3 + Tab genera una lista de tres elementos.` },
    { n: `3.2`, t: `Listas de definición`, m: `3 min`,
      b: [`La lista de descripción <dl> agrupa pares de término y descripción: un glosario, preguntas frecuentes o los datos de una ficha. Cada término va en <dt> y su descripción en <dd>. Un término puede tener varias descripciones.`],
      k: [`dl = la lista; dt = el término; dd = la descripción.`, `Ideal para glosarios, FAQ y fichas técnicas.`, `Puedes envolver cada pareja en un <div> para darle estilo.`],
      c: `<dl>\n  <dt>Fecha</dt>\n  <dd>12, 13 y 14 de junio</dd>\n  <dt>Lugar</dt>\n  <dd>IFEMA, Madrid</dd>\n  <dt>Edad mínima</dt>\n  <dd>16 años (menores, acompañados)</dd>\n</dl>`,
      tip: `para la sección de información práctica del proyecto del festival, una dl queda mucho más limpia que una tabla.` },
    { n: `3.3`, t: `Enlaces y rutas`, m: `5 min`,
      b: [`El elemento <a> (anchor) crea un enlace; su atributo href indica el destino. El texto del enlace debe decir a dónde lleva, porque quien usa un lector de pantalla suele navegar escuchando solo la lista de enlaces.`,
          `Una ruta absoluta incluye el dominio completo (https://…) y sirve para enlazar a otras webs. Una ruta relativa se calcula desde el archivo actual: contacto.html está en la misma carpeta, paginas/precios.html en una subcarpeta y ../index.html en la carpeta de arriba. Una ruta que empieza por / parte de la raíz del sitio.`],
      k: [`Absoluta: https://ejemplo.com/pagina.html`, `Relativa: precios.html · css/styles.css · ../index.html`, `/ al principio = desde la raíz del sitio.`, `Texto descriptivo: «Ver precios», no «haz clic aquí».`],
      a: [[`href`, `Destino del enlace (URL, ruta, #id, mailto:, tel:).`], [`target="_blank"`, `Abre en una pestaña nueva.`], [`rel="noopener"`, `Seguridad al abrir pestañas nuevas.`], [`download`, `Descarga el archivo en lugar de abrirlo.`], [`title`, `Texto extra que aparece al pasar el ratón.`]],
      c: `<p><a href="https://developer.mozilla.org/es/">MDN (otra web)</a></p>\n<p><a href="precios.html">Precios (misma carpeta)</a></p>\n<p><a href="../index.html">Volver al inicio (carpeta superior)</a></p>\n<p><a href="https://w3schools.com" target="_blank" rel="noopener">W3Schools en otra pestaña</a></p>`,
      e: `escribir rutas con barras invertidas (css\\styles.css) o con mayúsculas distintas al nombre real del archivo. En Windows funciona, pero en el servidor (Linux) da error 404.`,
      tip: `poned todos los nombres de archivo en minúsculas y sin espacios ni tildes: festival-entradas.html.` },
    { n: `3.4`, t: `Anclas, correo, teléfono y descargas`, m: `4 min`,
      b: [`Un enlace puede saltar a una parte de la misma página: le das un id al elemento de destino y enlazas con href="#ese-id". Así funcionan los índices y los botones de «volver arriba».`,
          `Con mailto: se abre el programa de correo con la dirección rellenada, y con tel: el móvil ofrece llamar. El atributo download hace que el navegador descargue el archivo enlazado (un PDF, por ejemplo) en lugar de abrirlo.`],
      k: [`href="#precios" salta al elemento con id="precios".`, `href="#" vuelve arriba del todo.`, `mailto:correo@ejemplo.com · tel:+34600000000`, `download="nombre.pdf" fuerza la descarga con ese nombre.`],
      c: `<nav>\n  <a href="#horarios">Horarios</a> ·\n  <a href="#contacto">Contacto</a>\n</nav>\n<h2 id="horarios">Horarios</h2>\n<p>Puertas a las 17:00.</p>\n<h2 id="contacto">Contacto</h2>\n<p><a href="mailto:info@festivaldaw.es?subject=Entradas">Escríbenos</a> o\n<a href="tel:+34600123456">llama al 600 123 456</a>.</p>\n<p><a href="normas.pdf" download>Descargar normas (PDF)</a></p>`,
      tip: `un id no puede repetirse en la misma página ni contener espacios.` },
    { n: `3.5`, t: `Menús de navegación`, m: `3 min`,
      b: [`Un menú es un conjunto de enlaces importantes, así que se marca con <nav>, y dentro, por convención, una lista <ul> con un enlace en cada <li>. La lista anuncia a los lectores de pantalla cuántas opciones hay.`,
          `Para indicar en qué página está el usuario se usa aria-current="page" en el enlace activo; con CSS se le puede dar un estilo distinto.`],
      k: [`nav > ul > li > a: la estructura clásica de un menú.`, `aria-current="page" marca la página actual.`, `Solo los menús principales van en <nav>, no cada grupo de enlaces.`, `El menú en horizontal se hace con CSS (display: flex).`],
      c: `<nav aria-label="Principal">\n  <ul>\n    <li><a href="index.html" aria-current="page">Inicio</a></li>\n    <li><a href="cartel.html">Cartel</a></li>\n    <li><a href="entradas.html">Entradas</a></li>\n    <li><a href="contacto.html">Contacto</a></li>\n  </ul>\n</nav>`,
      tip: `si hay dos nav en la página (principal y pie), diferenciadlos con aria-label.` }
  ]},
  { t: `Imágenes y multimedia`, d: `Imágenes, formatos, figuras, vídeo, audio, iframes y SVG.`, secciones: [
    { n: `4.1`, t: `La etiqueta img`, m: `5 min`,
      b: [`<img> inserta una imagen. Es un elemento vacío: src indica el archivo y alt es el texto alternativo, que se lee en voz alta para personas ciegas, aparece si la imagen no carga y ayuda a los buscadores. alt es obligatorio.`,
          `Si la imagen es puramente decorativa, se deja alt="" (vacío), y así el lector de pantalla la ignora. Indicar width y height (en píxeles, sin unidad) reserva el espacio antes de que cargue la imagen y evita que la página «salte».`],
      k: [`alt describe la imagen; nunca lo omitas.`, `Imagen decorativa: alt="".`, `width y height evitan saltos de diseño al cargar.`, `loading="lazy" retrasa la carga de las imágenes que no se ven todavía.`],
      a: [[`src`, `Ruta o URL de la imagen.`], [`alt`, `Texto alternativo. Obligatorio.`], [`width / height`, `Tamaño en píxeles; reserva el hueco.`], [`loading="lazy"`, `Carga la imagen cuando se acerca a la pantalla.`], [`title`, `Texto al pasar el ratón (no sustituye a alt).`]],
      c: `<img src="https://placehold.co/300x150?text=Escenario" alt="Escenario principal iluminado de noche" width="300" height="150">\n<img src="no-existe.jpg" alt="Esta imagen no existe: así se ve el alt" width="300" height="60">`,
      e: `escribir alt="imagen" o alt="foto". No aporta nada: describid lo que se ve y por qué importa en ese contexto.`,
      tip: `para un buen alt, imaginad que se lo contáis a alguien por teléfono.` },
    { n: `4.2`, t: `Formatos de imagen`, m: `3 min`, v: 0,
      b: [`Elegir bien el formato reduce mucho el peso de la página. JPG es para fotografías; PNG para imágenes con transparencias o capturas de pantalla; SVG para logos e iconos, porque son vectoriales y se ven nítidos a cualquier tamaño; y WebP o AVIF son formatos modernos que pesan bastante menos que JPG y PNG con la misma calidad.`,
          `Antes de subir una foto, redimensionadla al tamaño al que se va a mostrar: una foto de móvil de 4000 px para un hueco de 400 px desperdicia megas.`],
      k: [`Foto → JPG o WebP.`, `Logo, icono → SVG.`, `Transparencia o captura → PNG o WebP.`, `Comprime con herramientas como Squoosh antes de subir.`],
      a: [[`JPG`, `Fotografías. Sin transparencia.`], [`PNG`, `Transparencia, capturas, gráficos con texto.`], [`SVG`, `Vectorial: logos e iconos, se escala sin perder calidad.`], [`WebP / AVIF`, `Modernos y ligeros; sustituyen a JPG y PNG.`], [`GIF`, `Animaciones sencillas; mejor un vídeo corto.`]], at: `Cuándo usar cada formato`, ah: [`Formato`, `Úsalo para`],
      c: `<img src="img/cartel.webp" alt="Cartel del festival" width="800" height="1200">\n<img src="img/logo.svg" alt="Festival DAW" width="120" height="40">`,
      tip: `squoosh.app es gratuito y funciona en el navegador: comparad el peso antes y después.` },
    { n: `4.3`, t: `figure y figcaption`, m: `3 min`,
      b: [`<figure> agrupa un contenido autónomo, normalmente una imagen, un gráfico o un fragmento de código, con su pie de foto <figcaption>. El pie queda asociado semánticamente al contenido.`,
          `figcaption no sustituye al alt: alt describe la imagen para quien no la ve y figcaption es un texto visible para todos que la complementa.`],
      k: [`figure = contenido + su pie.`, `figcaption puede ir al principio o al final.`, `Sirve también para tablas, código o citas.`],
      c: `<figure>\n  <img src="https://placehold.co/320x160?text=Escenario+2025" alt="Público frente al escenario principal" width="320" height="160">\n  <figcaption>Edición 2025: más de 3.000 asistentes.</figcaption>\n</figure>`,
      tip: `en la galería del proyecto, cada foto con su figure y figcaption queda muy profesional.` },
    { n: `4.4`, t: `Imágenes adaptables`, m: `5 min`, v: 0,
      b: [`Con srcset ofreces varias versiones de la misma imagen a distintos tamaños, y sizes le dice al navegador qué ancho ocupará en pantalla. El navegador elige la más ligera que se vea bien: el móvil descarga la pequeña y el portátil, la grande.`,
          `<picture> va un paso más allá: con varios <source> puedes ofrecer formatos modernos (AVIF, WebP) con un <img> de respaldo, o incluso imágenes distintas según el tamaño de pantalla (dirección artística).`],
      k: [`srcset = lista de imágenes con su ancho (400w, 800w…).`, `sizes = cuánto ocupará la imagen en pantalla.`, `picture + source permite formatos modernos con respaldo.`, `El <img> final dentro de picture es obligatorio.`],
      a: [[`srcset="a.jpg 400w, b.jpg 800w"`, `Versiones disponibles y su ancho real.`], [`sizes="(max-width: 600px) 100vw, 50vw"`, `Ancho que ocupará según la pantalla.`], [`<source type="image/avif">`, `Formato alternativo dentro de picture.`], [`<source media="(min-width: 800px)">`, `Imagen distinta según el ancho.`]],
      c: `<img src="foto-800.jpg"\n     srcset="foto-400.jpg 400w, foto-800.jpg 800w, foto-1600.jpg 1600w"\n     sizes="(max-width: 600px) 100vw, 50vw"\n     alt="Escenario principal" width="800" height="450">\n\n<picture>\n  <source srcset="cartel.avif" type="image/avif">\n  <source srcset="cartel.webp" type="image/webp">\n  <img src="cartel.jpg" alt="Cartel del festival" width="600" height="900">\n</picture>`,
      tip: `en las herramientas de desarrollo (pestaña Red) podéis ver qué versión descarga el navegador al cambiar el tamaño.` },
    { n: `4.5`, t: `Vídeo y audio`, m: `4 min`,
      b: [`<video> y <audio> reproducen archivos multimedia sin plugins. El atributo controls muestra los botones de reproducción; sin él, el reproductor no tiene controles. Dentro se pueden poner varios <source> con formatos distintos, y el navegador usa el primero que entienda.`,
          `Para vídeos con voz conviene añadir subtítulos con <track> (archivo .vtt). El autoplay solo funciona si el vídeo está silenciado (muted), porque los navegadores bloquean el sonido automático.`],
      k: [`controls muestra los controles.`, `autoplay necesita muted para funcionar.`, `poster es la imagen que se ve antes de reproducir.`, `<track> añade subtítulos accesibles.`],
      a: [[`controls`, `Muestra play, volumen, pantalla completa…`], [`autoplay muted`, `Reproduce solo al cargar, sin sonido.`], [`loop`, `Repite al terminar.`], [`poster="img.jpg"`, `Imagen de portada del vídeo.`], [`preload="none"`, `No descarga nada hasta pulsar play.`], [`playsinline`, `En iPhone, no abre pantalla completa.`]],
      c: `<video controls width="320" poster="https://placehold.co/320x180?text=Aftermovie">\n  <source src="aftermovie.webm" type="video/webm">\n  <source src="aftermovie.mp4" type="video/mp4">\n  <track src="subtitulos.vtt" kind="subtitles" srclang="es" label="Español">\n  Tu navegador no puede reproducir este vídeo.\n</video>\n<audio controls src="himno.mp3"></audio>`,
      tip: `el texto que hay dentro de video solo se ve en navegadores que no lo soportan: es el «plan B».` },
    { n: `4.6`, t: `iframes y SVG`, m: `4 min`,
      b: [`<iframe> incrusta otra página dentro de la tuya: un mapa de Google, un vídeo de YouTube, un formulario externo. Necesita un title que describa su contenido. loading="lazy" evita cargarlo hasta que el usuario se acerca.`,
          `SVG es un formato de imagen vectorial escrito en XML. Se puede usar como archivo con <img src="logo.svg"> o escribir directamente en el HTML con <svg>, lo que permite cambiar sus colores con CSS. Es ideal para iconos.`],
      k: [`iframe siempre con title.`, `Los servicios dan el código del iframe en «Compartir → Insertar».`, `SVG en línea se puede colorear con CSS (fill).`, `viewBox define el sistema de coordenadas del SVG.`],
      a: [[`src`, `URL de la página incrustada.`], [`title`, `Describe el contenido (accesibilidad).`], [`width / height`, `Tamaño del marco.`], [`loading="lazy"`, `Carga diferida.`], [`allowfullscreen`, `Permite pantalla completa.`], [`sandbox`, `Restringe lo que puede hacer la página incrustada.`]], at: `Atributos de iframe`,
      c: `<svg width="120" height="120" viewBox="0 0 120 120" role="img" aria-label="Icono de nota musical">\n  <circle cx="60" cy="60" r="56" fill="#4F46E5"/>\n  <path d="M50 30v44a12 12 0 1 0 8 11V48l22-6v24a12 12 0 1 0 8 11V22z" fill="#fff"/>\n</svg>\n\n<!-- Ejemplo de iframe (Google Maps):\n<iframe src="https://www.google.com/maps/embed?..." title="Mapa de IFEMA"\n        width="600" height="400" loading="lazy"></iframe> -->`,
      tip: `cambiad fill="#4F46E5" por otro color en el ejemplo y mirad el resultado al instante.` }
  ]},
  { t: `Tablas`, d: `Datos tabulares, cabeceras, combinar celdas y tablas accesibles.`, secciones: [
    { n: `5.1`, t: `Estructura de una tabla`, m: `4 min`,
      b: [`Las tablas sirven para datos tabulares: información que se lee por filas y columnas, como horarios, precios o resultados. No deben usarse para maquetar la página (eso se hace con CSS Grid o Flexbox).`,
          `<table> envuelve la tabla, <tr> es cada fila (table row), <td> cada celda de datos (table data) y <th> cada celda de cabecera (table header), que se muestra en negrita y centrada.`],
      k: [`table > tr > td: tabla, fila, celda.`, `th = celda de cabecera.`, `Todas las filas deberían tener el mismo número de celdas.`, `Los bordes y el espaciado se ponen con CSS.`],
      a: [[`<table>`, `La tabla completa.`], [`<tr>`, `Una fila.`], [`<th>`, `Celda de cabecera.`], [`<td>`, `Celda de datos.`], [`<caption>`, `Título de la tabla.`]], at: `Elementos básicos`, ah: [`Elemento`, `Qué representa`],
      c: `<table>\n  <tr>\n    <th>Hora</th>\n    <th>Escenario</th>\n    <th>Artista</th>\n  </tr>\n  <tr>\n    <td>18:00</td>\n    <td>Principal</td>\n    <td>Banda A</td>\n  </tr>\n  <tr>\n    <td>20:00</td>\n    <td>Carpa</td>\n    <td>Banda B</td>\n  </tr>\n</table>`,
      e: `usar una tabla para colocar el logo a la izquierda y el menú a la derecha. Es una técnica de los años 90: hoy se usa Flexbox.`,
      tip: `en Emmet, table>tr*3>td*3 genera una tabla de 3×3.` },
    { n: `5.2`, t: `caption, thead, tbody y tfoot`, m: `4 min`,
      b: [`<caption> da un título a la tabla y debe ir justo después de <table>. Es lo primero que anuncia un lector de pantalla.`,
          `Las filas se agrupan en <thead> (cabecera), <tbody> (cuerpo) y <tfoot> (pie, por ejemplo con totales). Estos grupos ayudan a la accesibilidad, permiten dar estilo a cada parte y, al imprimir una tabla larga, el navegador repite la cabecera en cada página.`],
      k: [`caption va inmediatamente después de <table>.`, `thead = cabecera; tbody = datos; tfoot = totales.`, `Facilitan aplicar estilos: tbody tr:nth-child(even).`],
      c: `<table>\n  <caption>Precios de las entradas</caption>\n  <thead>\n    <tr><th>Tipo</th><th>Precio</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Abono 3 días</td><td>89 €</td></tr>\n    <tr><td>Entrada de día</td><td>39 €</td></tr>\n  </tbody>\n  <tfoot>\n    <tr><td>IVA incluido</td><td>21 %</td></tr>\n  </tfoot>\n</table>`,
      tip: `es justo lo que necesitáis para la sección de precios del proyecto del festival.` },
    { n: `5.3`, t: `Combinar celdas`, m: `4 min`,
      b: [`colspan hace que una celda ocupe varias columnas y rowspan que ocupe varias filas. Al combinar, hay que quitar las celdas que quedan «tapadas»; si no, la tabla se descuadra.`,
          `Un truco para no perderse: dibujad la tabla en papel con una cuadrícula y contad cuántas celdas reales tiene cada fila.`],
      k: [`colspan="2" ocupa dos columnas.`, `rowspan="3" ocupa tres filas.`, `Elimina las celdas que quedan cubiertas.`, `Dibuja la cuadrícula antes de escribir el código.`],
      a: [[`colspan="n"`, `La celda ocupa n columnas.`], [`rowspan="n"`, `La celda ocupa n filas.`], [`scope="col | row"`, `En un th: indica si es cabecera de columna o de fila.`], [`headers="id1 id2"`, `En un td: enlaza con sus cabeceras en tablas complejas.`]],
      c: `<table>\n  <tr><th>Día</th><th>Escenario</th><th>Artista</th></tr>\n  <tr><td rowspan="2">Viernes</td><td>Principal</td><td>Banda A</td></tr>\n  <tr><td>Carpa</td><td>Banda B</td></tr>\n  <tr><td>Sábado</td><td colspan="2">Cerrado por montaje</td></tr>\n</table>`,
      tip: `cambiad rowspan="2" por rowspan="1" en el ejemplo y veréis cómo se descuadra la tabla.` },
    { n: `5.4`, t: `Tablas accesibles`, m: `3 min`,
      b: [`Un lector de pantalla lee la tabla celda a celda. Para que diga «Precio: 39 €» y no solo «39 €», necesita saber qué cabecera corresponde a cada celda. Con scope="col" en las cabeceras de columna y scope="row" en las de fila queda claro.`,
          `Además: un caption que describa la tabla, nada de celdas vacías usadas como espaciadores y evitar tablas anidadas.`],
      k: [`scope="col" en cabeceras de columna.`, `scope="row" en la primera celda de cada fila si actúa de cabecera.`, `Siempre un caption.`, `En móvil, envuelve la tabla en un div con overflow-x: auto.`],
      c: `<table>\n  <caption>Aforo por zona</caption>\n  <tr>\n    <th scope="col">Zona</th>\n    <th scope="col">Aforo</th>\n  </tr>\n  <tr>\n    <th scope="row">Pista</th>\n    <td>2.000</td>\n  </tr>\n  <tr>\n    <th scope="row">Grada</th>\n    <td>1.200</td>\n  </tr>\n</table>`,
      tip: `probad la tabla con el lector de pantalla del sistema (Narrador en Windows, VoiceOver en Mac).` }
  ]},
  { t: `Formularios: lo esencial`, d: `form, input, label, select, textarea y botones.`, secciones: [
    { n: `6.1`, t: `El elemento form`, m: `5 min`, v: 0,
      b: [`<form> agrupa los campos que se envían juntos. action indica a qué URL se envían los datos (por ejemplo, un archivo PHP) y method cómo: GET los añade a la URL (?nombre=Ana&curso=DAW1) y POST los envía en el cuerpo de la petición, sin que se vean en la barra de direcciones.`,
          `Cada campo necesita un atributo name: es la clave con la que llega el dato al servidor ($_POST["email"] en PHP). Un campo sin name no se envía.`],
      k: [`action = a dónde; method = cómo (get o post).`, `GET para búsquedas y filtros; POST para datos privados o que cambian algo.`, `Sin name, el campo no se envía.`, `Al pulsar Enter en un campo, se envía el formulario.`],
      a: [[`action="procesar.php"`, `URL que recibe los datos.`], [`method="get | post"`, `Forma de enviar los datos.`], [`enctype="multipart/form-data"`, `Necesario para subir archivos.`], [`autocomplete="off"`, `Desactiva el autocompletado del navegador.`], [`novalidate`, `Desactiva la validación nativa.`]],
      c: `<form action="buscar.php" method="get">\n  <label for="q">Buscar artista</label>\n  <input id="q" name="q" type="search">\n  <button type="submit">Buscar</button>\n</form>\n<!-- Al enviar: buscar.php?q=texto -->`,
      e: `usar GET para un formulario de login. La contraseña quedaría en la URL, en el historial del navegador y en los registros del servidor.`,
      tip: `en las herramientas de desarrollo, pestaña Red, podéis ver qué datos envía un formulario.` },
    { n: `6.2`, t: `input y label`, m: `5 min`,
      b: [`<input> es el campo más versátil: su atributo type cambia completamente su comportamiento. Es un elemento vacío.`,
          `Cada campo debe tener un <label>. Se asocia con for, que debe coincidir con el id del campo. Así, al hacer clic en el texto se activa el campo (muy útil en móvil y en casillas pequeñas) y el lector de pantalla lee la etiqueta al llegar al campo. El placeholder no sustituye al label: desaparece al escribir.`],
      k: [`label for="x" ↔ input id="x".`, `name = clave para el servidor; id = enlace con el label.`, `placeholder es solo una pista de formato, no una etiqueta.`, `value da un valor inicial.`],
      a: [[`type`, `Tipo de campo (text, email, password…).`], [`name`, `Nombre con el que se envía el dato.`], [`id`, `Identificador; lo usa el label.`], [`value`, `Valor inicial o valor que se envía.`], [`placeholder`, `Texto de ejemplo dentro del campo.`], [`autocomplete="email"`, `Ayuda al navegador a autocompletar.`]],
      c: `<form>\n  <label for="nombre">Nombre</label><br>\n  <input id="nombre" name="nombre" type="text" placeholder="Ej.: Ana García" autocomplete="name"><br><br>\n  <label for="email">Correo</label><br>\n  <input id="email" name="email" type="email" placeholder="tu@correo.com" autocomplete="email">\n</form>`,
      e: `que el for del label no coincida exactamente con el id del input (por una mayúscula o una tilde). El clic en el texto deja de funcionar.`,
      tip: `haced clic en el texto «Nombre» del resultado: el cursor salta al campo. Eso es el label bien enlazado.` },
    { n: `6.3`, t: `Tipos de input`, m: `5 min`,
      b: [`Elegir el type correcto mejora mucho la experiencia: en el móvil, type="email" muestra un teclado con @, type="tel" un teclado numérico y type="date" un calendario. Además, algunos tipos validan solos el formato.`,
          `Las casillas (checkbox) permiten marcar varias opciones; los botones de opción (radio) solo una dentro de un grupo, que se define dándoles el mismo name.`],
      k: [`email, tel, url, number, date: teclado y validación adecuados.`, `password oculta lo que se escribe.`, `radio: mismo name = mismo grupo, solo uno marcado.`, `checked marca una casilla por defecto.`],
      a: [[`text`, `Texto de una línea.`], [`email`, `Correo; valida que tenga @ y dominio.`], [`password`, `Oculta los caracteres.`], [`number`, `Números; admite min, max y step.`], [`tel`, `Teléfono; teclado numérico en móvil.`], [`date / time`, `Selector de fecha / hora.`], [`checkbox`, `Casilla; se pueden marcar varias.`], [`radio`, `Opción única dentro de un grupo.`], [`range`, `Deslizador entre min y max.`], [`color`, `Selector de color.`], [`search`, `Campo de búsqueda.`], [`hidden`, `Campo oculto que se envía igualmente.`]], at: `Valores de type`, ah: [`type`, `Para qué sirve`],
      c: `<form>\n  <p><label>Entradas: <input type="number" name="cantidad" min="1" max="6" value="1"></label></p>\n  <p><label>Fecha: <input type="date" name="fecha"></label></p>\n  <p>Tipo de entrada:\n    <label><input type="radio" name="tipo" value="dia" checked> Día</label>\n    <label><input type="radio" name="tipo" value="abono"> Abono</label>\n  </p>\n  <p><label><input type="checkbox" name="parking"> Añadir parking</label></p>\n  <p><label>Volumen: <input type="range" min="0" max="10"></label></p>\n</form>`,
      tip: `fijaos en que el label también puede envolver al input; así no hacen falta for ni id.` },
    { n: `6.4`, t: `select, textarea y datalist`, m: `4 min`,
      b: [`<select> crea una lista desplegable con varias <option>. El value de cada opción es lo que se envía; el texto es lo que ve el usuario. Con <optgroup> se agrupan opciones y con multiple se pueden elegir varias.`,
          `<textarea> es un campo de texto de varias líneas (comentarios, mensajes); rows y cols marcan su tamaño inicial y su valor inicial va entre las etiquetas, no en value. <datalist> ofrece sugerencias a un input sin obligar a elegir una.`],
      k: [`option: value se envía, el texto se muestra.`, `selected marca la opción por defecto.`, `textarea tiene etiqueta de cierre.`, `datalist sugiere; select obliga a elegir.`],
      a: [[`<option value selected>`, `Opción; selected la marca por defecto.`], [`<optgroup label="…">`, `Agrupa opciones con un título.`], [`multiple`, `En select: permite elegir varias.`], [`rows / cols`, `En textarea: filas y columnas visibles.`], [`maxlength`, `Máximo de caracteres.`], [`list="id"`, `En input: lo enlaza con un datalist.`]],
      c: `<form>\n  <p><label for="zona">Zona</label>\n  <select id="zona" name="zona">\n    <optgroup label="General">\n      <option value="pista" selected>Pista</option>\n      <option value="grada">Grada</option>\n    </optgroup>\n    <optgroup label="Premium">\n      <option value="vip">VIP</option>\n    </optgroup>\n  </select></p>\n  <p><label for="ciudad">Ciudad</label>\n  <input id="ciudad" name="ciudad" list="ciudades">\n  <datalist id="ciudades"><option value="Madrid"><option value="Valencia"><option value="Sevilla"></datalist></p>\n  <p><label for="msg">Mensaje</label><br>\n  <textarea id="msg" name="mensaje" rows="3" cols="30" maxlength="300"></textarea></p>\n</form>`,
      tip: `escribid «Ma» en el campo Ciudad del resultado para ver las sugerencias del datalist.` },
    { n: `6.5`, t: `Botones`, m: `3 min`,
      b: [`<button> tiene tres tipos: submit envía el formulario (es el valor por defecto dentro de un form), reset vacía todos los campos y button no hace nada por sí solo: se usa con JavaScript.`,
          `Escribid siempre el type. Un botón sin type dentro de un formulario lo envía, y es una fuente típica de errores cuando ese botón solo debía abrir un menú. Usad <button> para acciones y <a> para navegar a otra página.`],
      k: [`type="submit" envía; type="reset" limpia; type="button" no hace nada.`, `Sin type, un botón dentro de un form es submit.`, `Botón = acción; enlace = navegación.`, `disabled desactiva el botón.`],
      c: `<form>\n  <input name="nombre" placeholder="Nombre">\n  <button type="submit">Enviar</button>\n  <button type="reset">Borrar</button>\n  <button type="button">Solo para JavaScript</button>\n  <button type="submit" disabled>Desactivado</button>\n</form>`,
      e: `usar un <div> con onclick como botón. No se puede usar con teclado ni lo anuncia el lector de pantalla; un <button> lo hace todo eso gratis.`,
      tip: `escribid algo en el campo del resultado y pulsad «Borrar» para ver el reset.` }
  ]},
  { t: `Formularios avanzados`, d: `Validación nativa, agrupar campos, estados y envío de archivos.`, secciones: [
    { n: `7.1`, t: `Validación nativa`, m: `5 min`,
      b: [`HTML puede validar los datos antes de enviarlos, sin JavaScript. required obliga a rellenar el campo; minlength y maxlength limitan la longitud del texto; min, max y step limitan números y fechas; y pattern exige que el valor cumpla una expresión regular.`,
          `Si algo no se cumple, el navegador bloquea el envío y muestra un mensaje. Con CSS se pueden marcar los campos con :invalid y :valid. Pero ojo: la validación del navegador se puede saltar, así que el servidor siempre debe volver a validar.`],
      k: [`required: campo obligatorio.`, `pattern="[0-9]{5}": expresión regular (aquí, 5 cifras).`, `title explica el formato esperado cuando falla pattern.`, `La validación real siempre se repite en el servidor.`],
      a: [[`required`, `El campo no puede quedar vacío.`], [`minlength / maxlength`, `Longitud mínima / máxima del texto.`], [`min / max`, `Valor mínimo / máximo (números y fechas).`], [`step`, `Saltos permitidos (step="0.01" para céntimos).`], [`pattern`, `Expresión regular que debe cumplir el valor.`], [`title`, `Se muestra como pista si no cumple el pattern.`]],
      c: `<form>\n  <p><label>Usuario (4-12 caracteres)<br>\n  <input name="usuario" required minlength="4" maxlength="12"></label></p>\n  <p><label>Código postal<br>\n  <input name="cp" required pattern="[0-9]{5}" title="5 cifras, por ejemplo 28042"></label></p>\n  <p><label>Edad<br><input type="number" name="edad" min="16" max="99" required></label></p>\n  <button type="submit">Comprobar</button>\n</form>`,
      e: `confiar solo en la validación de HTML. Cualquiera puede quitar required desde las herramientas de desarrollo y enviar lo que quiera.`,
      tip: `pulsad «Comprobar» en el resultado con los campos vacíos y luego con un código postal de 4 cifras.` },
    { n: `7.2`, t: `fieldset y legend`, m: `3 min`,
      b: [`<fieldset> agrupa campos relacionados (datos personales, dirección, forma de pago) y <legend> le da un título. Es imprescindible para grupos de radio o checkbox: el lector de pantalla lee la pregunta (el legend) antes de cada opción.`,
          `Además, poner disabled en un fieldset desactiva todos sus campos a la vez.`],
      k: [`fieldset agrupa; legend es su título.`, `Obligatorio para grupos de radio: da contexto a cada opción.`, `disabled en fieldset desactiva todo el grupo.`],
      c: `<form>\n  <fieldset>\n    <legend>Método de pago</legend>\n    <label><input type="radio" name="pago" value="tarjeta" checked> Tarjeta</label><br>\n    <label><input type="radio" name="pago" value="bizum"> Bizum</label>\n  </fieldset>\n  <fieldset disabled>\n    <legend>Factura (no disponible)</legend>\n    <input name="nif" placeholder="NIF">\n  </fieldset>\n</form>`,
      tip: `en formularios largos, un fieldset por bloque los hace mucho más fáciles de rellenar.` },
    { n: `7.3`, t: `Estados de los campos`, m: `4 min`,
      b: [`disabled desactiva un campo: no se puede editar y no se envía. readonly impide editarlo, pero sí se envía. autofocus pone el cursor en ese campo al cargar la página (solo uno por página).`,
          `autocomplete indica al navegador qué dato espera cada campo (name, email, tel, street-address, new-password…), así puede rellenarlo automáticamente. Es una gran ayuda, sobre todo en el móvil.`],
      k: [`disabled: no editable y no se envía.`, `readonly: no editable pero sí se envía.`, `autofocus: solo en un campo por página.`, `autocomplete con el valor adecuado ahorra tiempo al usuario.`],
      a: [[`disabled`, `Desactivado: ni se edita ni se envía.`], [`readonly`, `Solo lectura: se envía.`], [`autofocus`, `Recibe el foco al cargar.`], [`autocomplete="…"`, `Tipo de dato para autocompletar.`], [`inputmode="numeric"`, `Fuerza el teclado numérico en el móvil.`], [`spellcheck="false"`, `Desactiva el corrector ortográfico.`]],
      c: `<form>\n  <p><label>Pedido nº <input name="pedido" value="A-1024" readonly></label></p>\n  <p><label>Descuento <input name="descuento" value="0 %" disabled></label></p>\n  <p><label>Código de verificación <input name="codigo" inputmode="numeric" autocomplete="one-time-code"></label></p>\n  <p><label>Nueva contraseña <input type="password" name="pass" autocomplete="new-password"></label></p>\n</form>`,
      tip: `inputmode="numeric" es mejor que type="number" para códigos postales o tarjetas: no muestra flechas ni quita ceros a la izquierda.` },
    { n: `7.4`, t: `Subir archivos`, m: `4 min`, v: 0,
      b: [`Con <input type="file"> el usuario elige archivos de su equipo. accept limita los tipos (image/*, .pdf) y multiple permite seleccionar varios.`,
          `Para que el archivo llegue al servidor, el formulario necesita method="post" y enctype="multipart/form-data". Sin ese enctype solo se envía el nombre del archivo. En PHP, el archivo llega en $_FILES.`],
      k: [`method="post" + enctype="multipart/form-data": obligatorios.`, `accept filtra los tipos de archivo.`, `multiple permite varios archivos (name="fotos[]" en PHP).`, `El servidor debe comprobar tipo y tamaño: accept no es seguridad.`],
      a: [[`accept="image/*"`, `Solo imágenes.`], [`accept=".pdf,.docx"`, `Solo esas extensiones.`], [`multiple`, `Varios archivos a la vez.`], [`capture="environment"`, `En móvil, abre la cámara trasera.`]],
      c: `<form action="subir.php" method="post" enctype="multipart/form-data">\n  <label for="cv">Tu CV (PDF)</label>\n  <input id="cv" type="file" name="cv" accept=".pdf" required>\n  <label for="fotos">Fotos del evento</label>\n  <input id="fotos" type="file" name="fotos[]" accept="image/*" multiple>\n  <button type="submit">Subir</button>\n</form>`,
      e: `olvidar el enctype. El formulario parece funcionar, pero en el servidor $_FILES llega vacío.`,
      tip: `en PHP, revisad también upload_max_filesize en la configuración si los archivos grandes no llegan.` },
    { n: `7.5`, t: `Un formulario completo`, m: `5 min`,
      b: [`Un buen formulario junta todo lo anterior: cada campo con su label, el type adecuado, name para el servidor, autocomplete, validación nativa, grupos con fieldset y un botón de envío claro.`,
          `Pedid solo los datos que realmente necesitáis: cada campo de más reduce el número de personas que terminan el formulario.`],
      k: [`Un label por campo.`, `type, name y autocomplete correctos.`, `required en lo imprescindible.`, `Un texto de botón que diga la acción: «Comprar entradas», no «Enviar».`],
      c: `<form action="comprar.php" method="post">\n  <fieldset>\n    <legend>Tus datos</legend>\n    <p><label for="n">Nombre</label><br><input id="n" name="nombre" autocomplete="name" required></p>\n    <p><label for="e">Correo</label><br><input id="e" type="email" name="email" autocomplete="email" required></p>\n  </fieldset>\n  <fieldset>\n    <legend>Entradas</legend>\n    <p><label for="t">Tipo</label><br>\n    <select id="t" name="tipo"><option value="dia">Día (39 €)</option><option value="abono">Abono (89 €)</option></select></p>\n    <p><label for="c">Cantidad</label><br><input id="c" type="number" name="cantidad" min="1" max="6" value="1"></p>\n  </fieldset>\n  <p><label><input type="checkbox" name="acepto" required> Acepto las condiciones</label></p>\n  <button type="submit">Comprar entradas</button>\n</form>`,
      tip: `usad este formulario como plantilla para el proyecto y conectadlo luego con PHP.` }
  ]},
  { t: `Semántica y maquetación`, d: `Bloque y en línea, div y span, etiquetas semánticas y la estructura de una página.`, secciones: [
    { n: `8.1`, t: `Elementos de bloque y en línea`, m: `4 min`,
      b: [`Por defecto, cada elemento tiene un tipo de visualización. Los de bloque (h1, p, div, ul, section…) ocupan todo el ancho disponible y empiezan en una línea nueva. Los en línea (a, strong, em, span, img…) solo ocupan lo que mide su contenido y se colocan dentro del texto.`,
          `Esto se puede cambiar con la propiedad display de CSS, pero es importante conocer el comportamiento por defecto para entender por qué un elemento «salta» de línea.`],
      k: [`Bloque: nueva línea y todo el ancho.`, `En línea: dentro del texto, solo su ancho.`, `A los elementos en línea no se les aplica width ni margin vertical.`, `display: block | inline | inline-block | flex | grid lo cambia.`],
      c: `<div style="background:#EEF0FF">Soy un div (bloque)</div>\n<p style="background:#DCFCE7">Soy un párrafo (bloque) con un\n<span style="background:#FEF9C3">span (en línea)</span> y un\n<a href="#">enlace (en línea)</a> dentro.</p>`,
      tip: `en las herramientas de desarrollo, al pasar el ratón por un elemento se ve exactamente el espacio que ocupa.` },
    { n: `8.2`, t: `div y span`, m: `3 min`,
      b: [`<div> (bloque) y <span> (en línea) son contenedores genéricos sin ningún significado. Sirven para agrupar elementos y poder darles estilo con CSS o manipularlos con JavaScript, normalmente a través de una clase.`,
          `Antes de usar un div, preguntaos si existe una etiqueta con significado para ese contenido (header, nav, article…). Si la hay, usadla. Si no, un div es perfectamente válido.`],
      k: [`div = caja genérica de bloque.`, `span = trozo de texto genérico en línea.`, `Se les da estilo con class.`, `Primero la etiqueta semántica; el div, si no hay otra.`],
      c: `<div class="tarjeta" style="border:1px solid #ddd;border-radius:12px;padding:12px;max-width:260px">\n  <h3>Banda A</h3>\n  <p>Viernes · <span style="color:#4F46E5;font-weight:600">Escenario principal</span></p>\n</div>`,
      e: `la «divitis»: una página hecha solo de div anidados. Funciona visualmente, pero ni Google ni los lectores de pantalla entienden su estructura.`,
      tip: `en el inspector, una web bien hecha se entiende leyendo solo los nombres de las etiquetas.` },
    { n: `8.3`, t: `Etiquetas semánticas de estructura`, m: `5 min`,
      b: [`HTML5 añadió etiquetas que describen el papel de cada zona de la página. <header> es la cabecera (logo, título, menú); <nav>, la navegación principal; <main>, el contenido principal, único en la página; <footer>, el pie (contacto, copyright, enlaces legales).`,
          `Estas etiquetas actúan como puntos de referencia (landmarks): un usuario de lector de pantalla puede saltar directamente a main o a nav. También ayudan a los buscadores y hacen el código mucho más legible.`],
      k: [`header, nav, main, footer: las zonas principales.`, `Solo un main visible por página.`, `header y footer también pueden ir dentro de un article.`, `Se ven igual que un div: el cambio es de significado.`],
      a: [[`<header>`, `Cabecera de la página o de una sección.`], [`<nav>`, `Bloque de navegación principal.`], [`<main>`, `Contenido principal (uno por página).`], [`<section>`, `Sección temática con su propio título.`], [`<article>`, `Contenido independiente: noticia, post, tarjeta de producto.`], [`<aside>`, `Contenido relacionado pero secundario: barra lateral.`], [`<footer>`, `Pie de la página o de una sección.`]], at: `Etiquetas semánticas`, ah: [`Etiqueta`, `Cuándo usarla`],
      c: `<header style="background:#EEF0FF;padding:8px">\n  <strong>Festival DAW</strong>\n  <nav><a href="#">Cartel</a> · <a href="#">Entradas</a></nav>\n</header>\n<main style="padding:8px">\n  <h1>Festival DAW 2026</h1>\n  <p>Tres días de música.</p>\n</main>\n<footer style="background:#F3F4F6;padding:8px">\n  <small>© 2026 · Contacto</small>\n</footer>`,
      tip: `para el proyecto en grupo, repartid el trabajo por estas zonas: cada uno su section dentro de main.` },
    { n: `8.4`, t: `section, article y aside`, m: `5 min`,
      b: [`<section> agrupa contenido de un mismo tema y casi siempre empieza con un título (h2). <article> es un contenido que tiene sentido por sí solo, fuera de la página: una noticia, una entrada de blog, un comentario o la tarjeta de un artista. <aside> contiene información relacionada pero secundaria, como una barra lateral o un recuadro de «sabías que».`,
          `Una forma sencilla de decidir: si lo podrías publicar suelto en otra web, es un article; si es una parte de esta página con un tema, es una section; si es información complementaria, es un aside.`],
      k: [`section = un tema de la página, con título.`, `article = contenido autónomo, reutilizable.`, `aside = complementario, se podría quitar.`, `Pueden anidarse: una section con varios article.`],
      c: `<main>\n  <section>\n    <h2>Cartel</h2>\n    <article>\n      <h3>Banda A</h3>\n      <p>Rock alternativo desde Valencia.</p>\n    </article>\n    <article>\n      <h3>Banda B</h3>\n      <p>Pop electrónico.</p>\n    </article>\n  </section>\n  <aside>\n    <p><strong>¿Sabías que…?</strong> El festival empezó como un proyecto de clase.</p>\n  </aside>\n</main>`,
      tip: `si una section no tiene un título que poner, probablemente debería ser un div.` },
    { n: `8.5`, t: `time, address y otros elementos con significado`, m: `3 min`,
      b: [`<time> marca fechas y horas; su atributo datetime guarda el valor en formato estándar (2026-06-12 o 18:30), que pueden leer máquinas como Google o un calendario, mientras el texto se escribe como queramos.`,
          `<address> contiene los datos de contacto del autor o la empresa. Otros elementos útiles son <data> (un valor con su versión para máquinas) y <search>, nuevo en HTML, para envolver un formulario de búsqueda.`],
      k: [`<time datetime="2026-06-12T18:00">12 de junio, 18:00</time>`, `address = datos de contacto, no cualquier dirección postal.`, `datetime usa el formato AAAA-MM-DD y HH:MM.`],
      c: `<p>Puertas: <time datetime="2026-06-12T17:00">viernes 12 de junio a las 17:00</time>.</p>\n<footer>\n  <address>\n    Festival DAW · <a href="mailto:info@festivaldaw.es">info@festivaldaw.es</a><br>\n    Av. del Partenón, 5, Madrid\n  </address>\n</footer>`,
      tip: `Google puede mostrar las fechas de vuestros eventos en los resultados si usáis datos estructurados junto a time.` },
    { n: `8.6`, t: `Maqueta completa de una página`, m: `6 min`,
      b: [`Juntando todo, una página típica tiene: header con el logo y el nav, main con varias section (cada una con su h2), quizá un aside, y un footer. El HTML define la estructura y el CSS decide si el aside va a la derecha o debajo en el móvil.`,
          `Antes de escribir CSS, comprobad que la página tiene sentido sin estilos: los títulos forman un índice lógico, el orden de lectura es correcto y cada zona usa su etiqueta.`],
      k: [`header → nav → main (section…) → aside → footer.`, `Cada section, con su h2.`, `La página debe entenderse sin CSS.`, `Validad el HTML antes de empezar con los estilos.`],
      c: `<header>\n  <h1>Festival DAW 2026</h1>\n  <nav><ul><li><a href="#cartel">Cartel</a></li><li><a href="#entradas">Entradas</a></li></ul></nav>\n</header>\n<main>\n  <section id="cartel">\n    <h2>Cartel</h2>\n    <article><h3>Banda A</h3><p>Viernes, 21:00</p></article>\n  </section>\n  <section id="entradas">\n    <h2>Entradas</h2>\n    <p>Abono 3 días: 89 €</p>\n  </section>\n</main>\n<footer><p><small>© 2026 Festival DAW</small></p></footer>`,
      tip: `quitad el CSS de vuestro proyecto (en Firefox: Ver → Estilo de página → Sin estilo) y mirad si se entiende.` }
  ]},
  { t: `Atributos globales e interactividad nativa`, d: `id, class, data-*, details, dialog, progress y template.`, secciones: [
    { n: `9.1`, t: `Atributos globales`, m: `5 min`,
      b: [`Los atributos globales se pueden poner en cualquier elemento. Los más usados son id (identificador único en la página, para anclas, labels y JavaScript) y class (una o varias clases separadas por espacios, para aplicar estilos de CSS a grupos de elementos).`,
          `Otros útiles: title (texto al pasar el ratón), hidden (oculta el elemento), lang (idioma de un fragmento), tabindex (orden de foco con el teclado), contenteditable (permite editar el texto) y style (estilos en línea, mejor evitarlo y usar CSS).`],
      k: [`id: único en la página.`, `class: reutilizable, se pueden poner varias.`, `hidden oculta el elemento.`, `Mejor clases y un archivo CSS que el atributo style.`],
      a: [[`id`, `Identificador único (anclas, label, JavaScript).`], [`class`, `Clases para CSS; varias separadas por espacio.`], [`style`, `CSS en línea (evitarlo salvo casos puntuales).`], [`title`, `Información extra al pasar el ratón.`], [`hidden`, `Oculta el elemento.`], [`lang`, `Idioma de ese fragmento.`], [`tabindex="0"`, `Hace enfocable un elemento con el teclado.`], [`contenteditable`, `El usuario puede editar el contenido.`], [`translate="no"`, `Evita que el traductor lo traduzca (nombres de marca).`]], at: `Atributos globales`,
      c: `<p id="aviso" class="destacado grande" title="Información importante">Aforo limitado.</p>\n<p hidden>Este párrafo no se ve.</p>\n<p>El grupo canta <span lang="en">Bohemian Rhapsody</span>.</p>\n<p contenteditable style="border:1px dashed #999;padding:6px">Haz clic y edita este texto.</p>`,
      e: `repetir el mismo id en varios elementos. Los labels, las anclas y getElementById solo encuentran el primero.`,
      tip: `regla práctica: class para estilos, id para enlaces internos y JavaScript.` },
    { n: `9.2`, t: `Atributos data-*`, m: `3 min`,
      b: [`Los atributos data-* permiten guardar datos propios en un elemento HTML sin inventar atributos no válidos. El nombre lo eliges tú después de data-: data-precio, data-id, data-dia.`,
          `Desde JavaScript se leen con elemento.dataset (data-precio se convierte en dataset.precio) y desde CSS se pueden usar en selectores como [data-dia="viernes"].`],
      k: [`data-nombre="valor": datos propios válidos.`, `En JS: el.dataset.nombre.`, `data-fecha-inicio → dataset.fechaInicio (camelCase).`, `En CSS: [data-estado="agotado"] { … }`],
      c: `<ul>\n  <li data-dia="viernes" data-precio="39">Entrada viernes</li>\n  <li data-dia="sabado" data-precio="45" data-estado="agotado">Entrada sábado (agotada)</li>\n</ul>\n<style>\n  [data-estado="agotado"] { color: #999; text-decoration: line-through; }\n</style>`,
      tip: `es como guardamos en DevPath el slug de cada tarjeta para saber a qué tema lleva.` },
    { n: `9.3`, t: `details y summary`, m: `3 min`,
      b: [`<details> crea un bloque desplegable sin una sola línea de JavaScript: <summary> es el texto que siempre se ve y, al hacer clic, se muestra el resto del contenido. Con el atributo open empieza desplegado.`,
          `Si varios details comparten el mismo atributo name, funcionan como un acordeón: al abrir uno se cierran los demás.`],
      k: [`summary = título clicable.`, `open = desplegado al cargar.`, `Mismo name = acordeón (solo uno abierto).`, `Accesible con teclado de serie.`],
      c: `<details name="faq" open>\n  <summary>¿Puedo salir y volver a entrar?</summary>\n  <p>Sí, con la pulsera puesta.</p>\n</details>\n<details name="faq">\n  <summary>¿Hay guardarropa?</summary>\n  <p>Sí, junto a la entrada principal (3 €).</p>\n</details>\n<details name="faq">\n  <summary>¿Se puede pagar con tarjeta?</summary>\n  <p>Sí, en todas las barras.</p>\n</details>`,
      tip: `perfecto para la sección de preguntas frecuentes del proyecto del festival.` },
    { n: `9.4`, t: `dialog`, m: `4 min`, v: 0,
      b: [`<dialog> es una ventana modal nativa. Se abre con JavaScript: showModal() la muestra encima de todo, oscurece el fondo (::backdrop) y bloquea el resto de la página; close() la cierra, y también se cierra con la tecla Escape.`,
          `Dentro, un <form method="dialog"> cierra el diálogo al pulsar su botón, sin enviar nada al servidor. Así se evita programar a mano el foco, el fondo o la tecla Escape.`],
      k: [`showModal() abre como modal; close() cierra.`, `Escape la cierra automáticamente.`, `form method="dialog" cierra al enviar.`, `El fondo se estiliza con dialog::backdrop.`],
      c: `<button type="button" onclick="document.getElementById('aviso').showModal()">Ver normas</button>\n\n<dialog id="aviso">\n  <h2>Normas del recinto</h2>\n  <p>No se permite entrar con bebidas.</p>\n  <form method="dialog">\n    <button>Entendido</button>\n  </form>\n</dialog>`,
      tip: `la vista previa de las lecciones no ejecuta JavaScript; probadlo en un archivo .html propio.` },
    { n: `9.5`, t: `progress, meter y output`, m: `3 min`,
      b: [`<progress> muestra el avance de una tarea (una descarga, un formulario por pasos) con value y max; sin value, muestra una animación de «cargando». <meter> representa una medida dentro de un rango conocido, como el aforo ocupado o la fuerza de una contraseña; con low, high y optimum el navegador lo colorea.`,
          `<output> muestra el resultado de un cálculo, normalmente actualizado con JavaScript.`],
      k: [`progress = avance de una tarea.`, `meter = medida en un rango (low, high, optimum).`, `Añade el valor en texto dentro para accesibilidad.`],
      c: `<p>Descarga: <progress value="70" max="100">70 %</progress></p>\n<p>Cargando: <progress></progress></p>\n<p>Aforo del viernes: <meter value="0.85" low="0.5" high="0.8" optimum="0.2">85 %</meter> 85 %</p>\n<p>Aforo del sábado: <meter value="0.3" low="0.5" high="0.8" optimum="0.2">30 %</meter> 30 %</p>`,
      tip: `fijaos en cómo cambia el color del meter según el valor.` },
    { n: `9.6`, t: `template y popover`, m: `4 min`, v: 0,
      b: [`<template> guarda un fragmento de HTML que no se muestra ni se procesa hasta que JavaScript lo clona. Es útil para repetir una estructura, por ejemplo una tarjeta por cada producto que llega de una API.`,
          `El atributo popover convierte un elemento en una capa emergente. Un botón con popovertarget lo abre y lo cierra, también con Escape o al hacer clic fuera, sin escribir JavaScript.`],
      k: [`template no se pinta: es un molde.`, `En JS: template.content.cloneNode(true).`, `popover + popovertarget = menú o aviso emergente sin JS.`],
      c: `<button popovertarget="info">Más información</button>\n<div id="info" popover>\n  <p>Las puertas abren a las 17:00.</p>\n</div>\n\n<template id="tarjeta">\n  <article class="artista">\n    <h3></h3>\n    <p></p>\n  </article>\n</template>`,
      tip: `en la asignatura de JavaScript usaréis template para pintar listas de datos.` }
  ]},
  { t: `Accesibilidad, SEO y rendimiento`, d: `Webs que todos pueden usar, que Google entiende y que cargan rápido.`, secciones: [
    { n: `10.1`, t: `Accesibilidad: lo básico`, m: `5 min`,
      b: [`Una web accesible la puede usar cualquier persona: quien usa un lector de pantalla, quien navega solo con teclado, quien ve mal los colores o quien tiene el brazo escayolado. En la Unión Europea es además una obligación legal para muchas webs.`,
          `La mayor parte de la accesibilidad viene de usar bien HTML: títulos en orden, alt en las imágenes, label en cada campo, botones que sean <button>, enlaces que sean <a>, lang en el html y suficiente contraste de color. Probad siempre a recorrer la página solo con la tecla Tab.`],
      k: [`HTML semántico = el 80 % de la accesibilidad.`, `Todo debe poder usarse con teclado (Tab, Enter, Espacio).`, `No transmitas información solo con color.`, `Contraste mínimo del texto: 4,5:1.`],
      a: [[`alt`, `Texto alternativo en imágenes.`], [`<label for>`, `Nombre de cada campo de formulario.`], [`lang`, `Idioma para la pronunciación.`], [`h1–h6 en orden`, `Índice navegable de la página.`], [`<button> / <a>`, `Controles usables con teclado.`], [`:focus-visible`, `Indicador visible del foco (CSS).`]], at: `Lista de comprobación`, ah: [`Qué`, `Por qué`],
      c: `<a href="#contenido" class="saltar">Saltar al contenido</a>\n<header><nav><a href="#">Inicio</a></nav></header>\n<main id="contenido">\n  <h1>Entradas</h1>\n  <img src="https://placehold.co/200x80?text=Mapa" alt="Mapa del recinto con tres escenarios" width="200" height="80">\n  <p><span style="color:#B91C1C">●</span> Agotado (en rojo y con texto)</p>\n</main>`,
      tip: `pasad la extensión WAVE o Lighthouse (pestaña de las DevTools) a vuestro proyecto: os dirá qué falta.` },
    { n: `10.2`, t: `ARIA y landmarks`, m: `5 min`,
      b: [`ARIA (Accessible Rich Internet Applications) son atributos que añaden información para tecnologías de apoyo cuando HTML no basta. aria-label da nombre a un elemento sin texto visible (un botón con solo un icono), aria-expanded indica si un menú está abierto y aria-live anuncia cambios en una zona de la página.`,
          `La primera regla de ARIA es no usarlo si existe un elemento HTML que ya hace lo mismo. Un <button> ya es un botón; un <div role="button"> necesita además tabindex y JavaScript para el teclado. Un ARIA mal puesto es peor que no poner nada.`],
      k: [`Primero HTML nativo; ARIA solo si hace falta.`, `aria-label: nombre accesible para iconos.`, `aria-hidden="true": oculta elementos decorativos al lector.`, `aria-live="polite": anuncia mensajes que aparecen.`],
      a: [[`aria-label`, `Nombre accesible cuando no hay texto visible.`], [`aria-labelledby`, `Toma el nombre de otro elemento por su id.`], [`aria-describedby`, `Enlaza un texto de ayuda o de error.`], [`aria-expanded`, `true/false: si un desplegable está abierto.`], [`aria-current="page"`, `Marca la página actual en un menú.`], [`aria-hidden="true"`, `Oculta un elemento a los lectores de pantalla.`], [`aria-live="polite"`, `Anuncia cambios de contenido.`], [`role`, `Define el papel de un elemento (alert, dialog…).`]], at: `Atributos ARIA más usados`,
      c: `<button type="button" aria-label="Cerrar menú">✕</button>\n<button type="button" aria-expanded="false" aria-controls="menu">Menú</button>\n\n<label for="pass">Contraseña</label>\n<input id="pass" type="password" aria-describedby="ayuda">\n<p id="ayuda"><small>Mínimo 8 caracteres.</small></p>\n\n<p aria-live="polite">Entrada añadida al carrito.</p>\n<span aria-hidden="true">★★★</span>`,
      tip: `una buena forma de aprender ARIA es inspeccionar componentes de webs grandes como GOV.UK.` },
    { n: `10.3`, t: `SEO en el HTML`, m: `5 min`, v: 0,
      b: [`El SEO (posicionamiento en buscadores) empieza en el HTML. Google usa el title como título del resultado y normalmente la meta description como texto debajo. Cada página debe tener un title y una description únicos y descriptivos.`,
          `También importan un h1 claro con el tema de la página, URLs legibles (/entradas en vez de /p?id=7), textos de enlace descriptivos, alt en las imágenes y la etiqueta canonical cuando el mismo contenido está en varias URLs. Un HTML semántico ayuda al buscador a entender qué es cada parte.`],
      k: [`title único: unos 50-60 caracteres.`, `meta description: unos 150 caracteres que inviten a hacer clic.`, `Un h1 por página con la palabra clave.`, `rel="canonical" indica la URL principal.`],
      a: [[`<title>`, `Título del resultado en Google.`], [`<meta name="description">`, `Texto bajo el título del resultado.`], [`<link rel="canonical">`, `URL oficial si hay duplicados.`], [`<meta name="robots" content="noindex">`, `Pide no aparecer en buscadores.`], [`<html lang>`, `Idioma de la página.`], [`<script type="application/ld+json">`, `Datos estructurados (eventos, productos…).`]], at: `Etiquetas para SEO`, ah: [`Etiqueta`, `Función`],
      c: `<head>\n  <title>Entradas Festival DAW 2026 · Madrid, 12-14 junio</title>\n  <meta name="description" content="Compra tus entradas para el Festival DAW 2026 en IFEMA Madrid. Abono 3 días desde 89 €.">\n  <link rel="canonical" href="https://festivaldaw.es/entradas">\n  <script type="application/ld+json">\n  {"@context":"https://schema.org","@type":"MusicEvent","name":"Festival DAW 2026","startDate":"2026-06-12","location":{"@type":"Place","name":"IFEMA Madrid"}}\n  </script>\n</head>`,
      tip: `buscad vuestra web con site:vuestrodominio.com para ver cómo la muestra Google.` },
    { n: `10.4`, t: `Open Graph y favicon`, m: `3 min`, v: 0,
      b: [`Cuando se comparte un enlace en WhatsApp, LinkedIn o X, la red lee las etiquetas Open Graph (og:) para mostrar una tarjeta con título, descripción e imagen. Sin ellas, la vista previa sale vacía o con datos al azar.`,
          `El favicon es el icono de la pestaña y de los marcadores. Un SVG sirve para todos los tamaños, y apple-touch-icon es el que usa el iPhone al añadir la web a la pantalla de inicio.`],
      k: [`og:title, og:description, og:image y og:url.`, `La imagen OG suele ser de 1200×630 px.`, `La URL de og:image debe ser absoluta.`, `Favicon SVG + apple-touch-icon PNG de 180×180.`],
      c: `<meta property="og:title" content="Festival DAW 2026">\n<meta property="og:description" content="Tres días de música en Madrid.">\n<meta property="og:image" content="https://festivaldaw.es/img/og.jpg">\n<meta property="og:url" content="https://festivaldaw.es">\n<meta name="twitter:card" content="summary_large_image">\n<link rel="icon" href="/favicon.svg" type="image/svg+xml">\n<link rel="apple-touch-icon" href="/apple-touch-icon.png">`,
      tip: `probad cómo se ve vuestro enlace pegándolo en un chat de WhatsApp contigo mismo.` },
    { n: `10.5`, t: `Rendimiento`, m: `5 min`, v: 0,
      b: [`Una web lenta pierde visitas. Desde el HTML se puede ayudar mucho: imágenes con width, height y loading="lazy"; scripts con defer para no bloquear el dibujado de la página; y preconnect para adelantar la conexión con servidores externos, como Google Fonts.`,
          `defer descarga el script en paralelo y lo ejecuta cuando el HTML está listo, respetando el orden. async lo ejecuta en cuanto llega, sin orden: sirve para scripts independientes, como la analítica.`],
      k: [`Imágenes: tamaño correcto, formato moderno, lazy.`, `Scripts: defer (o async si son independientes).`, `preconnect para dominios externos.`, `Mide con Lighthouse en las DevTools.`],
      a: [[`loading="lazy"`, `Imágenes e iframes fuera de pantalla, después.`], [`fetchpriority="high"`, `Prioriza la imagen principal (la de cabecera).`], [`decoding="async"`, `Decodifica la imagen sin bloquear.`], [`<script defer>`, `Ejecuta al terminar el HTML, en orden.`], [`<script async>`, `Ejecuta al llegar, sin orden.`], [`<link rel="preconnect">`, `Adelanta la conexión a otro dominio.`], [`<link rel="preload">`, `Descarga pronto un recurso crítico.`]], at: `Atributos de rendimiento`,
      c: `<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preload" href="img/cabecera.webp" as="image">\n<script src="js/app.js" defer></script>\n<script src="https://analitica.ejemplo/a.js" async></script>\n\n<img src="img/cabecera.webp" alt="Escenario" width="1200" height="600" fetchpriority="high">\n<img src="img/galeria-1.webp" alt="Público" width="600" height="400" loading="lazy">`,
      e: `poner loading="lazy" en la imagen principal de arriba del todo. La retrasa justo a ella, que es la primera que el usuario ve.`,
      tip: `en Lighthouse, intentad que vuestro proyecto supere 90 en Rendimiento y Accesibilidad.` },
    { n: `10.6`, t: `Validación y buenas prácticas`, m: `4 min`, v: 0,
      b: [`El validador del W3C (validator.w3.org) revisa el HTML y avisa de etiquetas mal cerradas, atributos inválidos o ids repetidos. Un HTML válido se comporta igual en todos los navegadores y es más fácil de mantener.`,
          `Buenas prácticas para el día a día: minúsculas y comillas dobles, indentación coherente, nombres de archivo sin espacios ni tildes, un archivo CSS y uno JS externos en lugar de estilos y scripts en línea, y comentarios para separar las secciones.`],
      k: [`Validad en validator.w3.org antes de entregar.`, `Minúsculas, comillas dobles y sangría de 2 espacios.`, `Archivos: festival-entradas.html, no Festival Entradas.HTML.`, `CSS y JS en archivos aparte.`],
      a: [[`index.html`, `Página principal en la raíz.`], [`css/`, `Hojas de estilo.`], [`js/`, `Scripts.`], [`img/`, `Imágenes optimizadas.`], [`README.md`, `Explicación del proyecto (para GitHub).`]], at: `Estructura de carpetas recomendada`, ah: [`Archivo o carpeta`, `Contenido`],
      c: `proyecto-festival/\n├── index.html\n├── entradas.html\n├── css/\n│   └── styles.css\n├── js/\n│   └── app.js\n├── img/\n│   ├── logo.svg\n│   └── cartel.webp\n└── README.md`,
      tip: `instalad Prettier en VS Code y activad «formatear al guardar»: el código del grupo quedará siempre igual de ordenado.` }
  ]}
]};
